-- F06 필터 옵션(F-1): runner.py(mode=new)가 조합별로 만든 실제 SQL(상수 배열·날짜 치환 완료). 계약 §3 술어 규약: WHERE 는 불리언·= ANY(상수)만, 비트식은 FILTER 안.
-- 조합 대표 4개: C01 글로벌 스냅샷, C05 글로벌 1년, C08 웹 스냅샷, C11 웹 1년. 전 조합 SQL: res/values-190616/values-new.jsonl.sql.jsonl

-- [C01 문장 1] 15.97 ms, 68 행
SELECT DISTINCT a.geo_key, a.engine_key FROM rd.answer a WHERE a.surface = 1 AND a.round_date = DATE '2026-09-14' AND a.cyc_key = ANY('{873}'::int[]) AND a.bgrp = ANY('{1,3,5,7,8,9,10,11,12,13,14,15,17,19,21,23,24,25,26,27,28,29,30,31}'::int2[]) AND a.std_in;

-- [C05 문장 1] 35.56 ms, 68 행
